// CloudServiceHandler is an implementation of the cloud.v1.CloudService service.
type CloudServiceHandler interface {
	// GetServiceInfo returns the version and public URL of this server.
	// It does not need a session.
	GetServiceInfo(context.Context, *connect.Request[v1.GetServiceInfoRequest]) (*connect.Response[v1.GetServiceInfoResponse], error)
	// GetCurrentUser returns the signed in user and the tenants they belong to.
	GetCurrentUser(context.Context, *connect.Request[v1.GetCurrentUserRequest]) (*connect.Response[v1.GetCurrentUserResponse], error)
	// ListInstallations returns the GitHub accounts the App is installed on for one tenant.
	ListInstallations(context.Context, *connect.Request[v1.ListInstallationsRequest]) (*connect.Response[v1.ListInstallationsResponse], error)
	// GetInstallURL returns the GitHub page where the user installs the App for one tenant.
	GetInstallURL(context.Context, *connect.Request[v1.GetInstallURLRequest]) (*connect.Response[v1.GetInstallURLResponse], error)
	// LinkPendingInstallation links an installation the setup callback could
	// not link yet because the webhook that names its installer had not
	// arrived. Only the GitHub user who installed it can link it.
	LinkPendingInstallation(context.Context, *connect.Request[v1.LinkPendingInstallationRequest]) (*connect.Response[v1.LinkPendingInstallationResponse], error)
	// CreateEnrollmentToken mints a one time token an agent uses to join one tenant.
	CreateEnrollmentToken(context.Context, *connect.Request[v1.CreateEnrollmentTokenRequest]) (*connect.Response[v1.CreateEnrollmentTokenResponse], error)
	// ListAgents returns the agents of one tenant with their live status.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	// DeleteAgent removes an agent and closes its command stream.
	DeleteAgent(context.Context, *connect.Request[v1.DeleteAgentRequest]) (*connect.Response[v1.DeleteAgentResponse], error)
	// UpdateMachineSettings changes the runner image of the tenant's own machines, owners only.
	UpdateMachineSettings(context.Context, *connect.Request[v1.UpdateMachineSettingsRequest]) (*connect.Response[v1.UpdateMachineSettingsResponse], error)
	// ListRepositories returns the enabled repositories of one tenant. Name,
	// visibility and archived state of each are read live from GitHub by
	// repository id with a 30 second cache. A repository GitHub does not
	// return gets the problem status.
	ListRepositories(context.Context, *connect.Request[v1.ListRepositoriesRequest]) (*connect.Response[v1.ListRepositoriesResponse], error)
	// ListInstallationRepositories returns every repository the GitHub App
	// installations of one tenant can see, read live from GitHub without a
	// cache. The dashboard calls it only when a user opens the repository
	// picker. Suspended installations are skipped.
	ListInstallationRepositories(context.Context, *connect.Request[v1.ListInstallationRepositoriesRequest]) (*connect.Response[v1.ListInstallationRepositoriesResponse], error)
	// EnableRepository lets jobs of the repository with runs-on: elastic-fruit
	// run on Elastic Fruit, owners only. The repository must be readable
	// through the given installation of the tenant.
	EnableRepository(context.Context, *connect.Request[v1.EnableRepositoryRequest]) (*connect.Response[v1.EnableRepositoryResponse], error)
	// DisableRepository stops running jobs of the repository, owners only. Job history stays.
	DisableRepository(context.Context, *connect.Request[v1.DisableRepositoryRequest]) (*connect.Response[v1.DisableRepositoryResponse], error)
	// ListJobs returns one page of job history of one tenant, newest first.
	ListJobs(context.Context, *connect.Request[v1.ListJobsRequest]) (*connect.Response[v1.ListJobsResponse], error)
	// GetJob returns one job with its resource samples.
	GetJob(context.Context, *connect.Request[v1.GetJobRequest]) (*connect.Response[v1.GetJobResponse], error)
	// GetJobLogs returns the end of the GitHub log of one job. The server finds
	// the GitHub workflow job through the GitHub App installation of the
	// tenant, which needs the Actions read permission. When the log cannot be
	// read, status says why and the response still links the run on GitHub.
	GetJobLogs(context.Context, *connect.Request[v1.GetJobLogsRequest]) (*connect.Response[v1.GetJobLogsResponse], error)
	// GetOverview returns the counts shown on the overview page.
	GetOverview(context.Context, *connect.Request[v1.GetOverviewRequest]) (*connect.Response[v1.GetOverviewResponse], error)
	// ListMembers returns the members of one tenant and its open invites.
	ListMembers(context.Context, *connect.Request[v1.ListMembersRequest]) (*connect.Response[v1.ListMembersResponse], error)
	// InviteMember creates an invite for a GitHub login, owners only. The
	// invite is claimed when that login signs in, or through the returned link.
	InviteMember(context.Context, *connect.Request[v1.InviteMemberRequest]) (*connect.Response[v1.InviteMemberResponse], error)
	// RevokeInvite deletes an open invite, owners only.
	RevokeInvite(context.Context, *connect.Request[v1.RevokeInviteRequest]) (*connect.Response[v1.RevokeInviteResponse], error)
	// RemoveMember removes one member from a tenant, owners only. The last owner cannot be removed.
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	// LeaveTenant removes the signed in user from a tenant. The last owner cannot leave.
	LeaveTenant(context.Context, *connect.Request[v1.LeaveTenantRequest]) (*connect.Response[v1.LeaveTenantResponse], error)
	// AcceptInvite joins the signed in user to the tenant named by an invite link token.
	AcceptInvite(context.Context, *connect.Request[v1.AcceptInviteRequest]) (*connect.Response[v1.AcceptInviteResponse], error)
	// DeleteTenant removes a tenant that has no installations, agents or enabled repositories left, owners only.
	DeleteTenant(context.Context, *connect.Request[v1.DeleteTenantRequest]) (*connect.Response[v1.DeleteTenantResponse], error)
	// GetUsageReport returns the stored daily usage of one tenant per
	// repository for the last days, with totals.
	GetUsageReport(context.Context, *connect.Request[v1.GetUsageReportRequest]) (*connect.Response[v1.GetUsageReportResponse], error)
	// ExportUsageCSV returns the daily usage rows of one tenant between two days as CSV text.
	ExportUsageCSV(context.Context, *connect.Request[v1.ExportUsageCSVRequest]) (*connect.Response[v1.ExportUsageCSVResponse], error)
	// CreateAPIToken creates an API token for one tenant, owners with a browser
	// session only. The token is returned once, the server only stores its hash.
	CreateAPIToken(context.Context, *connect.Request[v1.CreateAPITokenRequest]) (*connect.Response[v1.CreateAPITokenResponse], error)
	// ListAPITokens returns the API tokens of one tenant, revoked and expired
	// ones included, owners with a browser session only.
	ListAPITokens(context.Context, *connect.Request[v1.ListAPITokensRequest]) (*connect.Response[v1.ListAPITokensResponse], error)
	// RevokeAPIToken stops an API token from working, owners with a browser session only.
	RevokeAPIToken(context.Context, *connect.Request[v1.RevokeAPITokenRequest]) (*connect.Response[v1.RevokeAPITokenResponse], error)
}

